import { mediaUrl } from "@/lib/media";
import type { ServiceImageAsset, ServiceImageSet } from "@/lib/service-images";

function asset(
  path: string, alt: string, width: number, height: number, photographer: string, unsplashId: string
): ServiceImageAsset {
  return { path, alt, width, height, photographer, unsplashId };
}

export function blogImageSrc(image: ServiceImageAsset): string {
  return mediaUrl(image.path);
}

